#include "ui/UserLoginWindow.h"
#include "ui_UserLoginWindow.h"   // generated by AUTOUIC from UserLoginWindow.ui

#include <QLineEdit>
#include <QStyle>

#include "application/loginusecase/AuthError.h"
#include "ui/LoginController.h"
#include "ui/UiTexts.h"

namespace ui {

UserLoginWindow::UserLoginWindow(LoginController& controller, QWidget* parent)
    : QDialog(parent)
    , m_ui(std::make_unique<Ui::UserLoginWindow>())
    , m_controller(controller)
{
    m_ui->setupUi(this);

    // The dialog takes the exact size of its content (also when the message banner appears).
    m_ui->rootLayout->setSizeConstraint(QLayout::SetFixedSize);

    // Hints for virtual keyboards / input methods: no auto-capitalisation, no learning of what is typed.
    // important to reach the specification of portability and scalability
    m_ui->loginEdit->setInputMethodHints(Qt::ImhNoAutoUppercase | Qt::ImhNoPredictiveText);
    m_ui->passwordEdit->setInputMethodHints(Qt::ImhSensitiveData | Qt::ImhNoPredictiveText | Qt::ImhNoAutoUppercase);

    m_countdownTimer.setInterval(1000); // countdown tick = 1 second

    /* **********************************************
     *            UI events :
     * ********************************************** */

    // signInButton: QPushButton ---> login request
    connect(m_ui->signInButton, &QPushButton::clicked, this, &UserLoginWindow::onSignInClicked);

    // erase the default display and let the user type his/her login
    connect(m_ui->loginEdit, &QLineEdit::textChanged, this, &UserLoginWindow::onInputChanged);
    connect(m_ui->passwordEdit, &QLineEdit::textChanged, this, &UserLoginWindow::onInputChanged);

    connect(m_ui->showPasswordCheck, &QCheckBox::toggled, this, &UserLoginWindow::onShowPasswordToggled);
    connect(m_ui->loginEdit, &QLineEdit::returnPressed, this, [this]() { m_ui->passwordEdit->setFocus(); });

    // Enter inside the password field is handled by the dialog's default button (signInButton).
    // Results from the controller (always delivered in the UI thread)
    connect(&m_controller, &LoginController::loginSucceeded, this, &UserLoginWindow::onLoginSucceeded);
    connect(&m_controller, &LoginController::loginFailed, this, &UserLoginWindow::onLoginFailed);
    // Timer tick, count-down to stop the process if it is to long to complete
    connect(&m_countdownTimer, &QTimer::timeout, this, &UserLoginWindow::onCountdownTick);

    prepareForNewSession();
}

UserLoginWindow::~UserLoginWindow() = default;

void UserLoginWindow::prepareForNewSession()
{
    stopCountdown();
    m_pending = false;
    m_signedInLogin.clear();
    m_ui->loginEdit->clear();
    m_ui->passwordEdit->clear();
    m_ui->showPasswordCheck->setChecked(false);
    clearMessage();
    setBusy(false);
    m_ui->loginEdit->setFocus();
}

void UserLoginWindow::reject()
{
    m_pending = false;        // a late answer from the worker is ignored
    stopCountdown();
    QDialog::reject();
}

void UserLoginWindow::onSignInClicked()
{
    if (m_busy || m_lockedSeconds > 0) {
        return;
    }

    const QString login = m_ui->loginEdit->text();
    const QString password = m_ui->passwordEdit->text();   // never trimmed, never logged (UC1-11)

    if (login.trimmed().isEmpty() || password.isEmpty()) {
        return;               // check only; the button is normally disabled in that case
    }

    // The password is buffered to be sent: do not keep it in the widget.
    m_ui->passwordEdit->clear();

    clearMessage();
    setBusy(true);
    m_pending = true;    

    m_controller.submit(login, password);


}

void UserLoginWindow::onInputChanged()
{
    updateSignInButton();
}

void UserLoginWindow::onShowPasswordToggled(bool visible)
{
    m_ui->passwordEdit->setEchoMode(visible ? QLineEdit::Normal : QLineEdit::Password);
}

void UserLoginWindow::onLoginSucceeded(const QString& login, int role)
{
    if (!m_pending) {
        return;               // the user closed the window meanwhile
    }
    m_pending = false;

    m_signedInLogin = login;
    m_signedInRole = static_cast<domain::UserRole>(role);

    setBusy(false);
    clearMessage();
    accept();                 // emits accepted(): main() opens the chat window
}

void UserLoginWindow::onLoginFailed(int authError, int retryAfterSeconds)
{
    if (!m_pending) {
        return;
    }
    m_pending = false;

    setBusy(false);

    // int to enum
    const auto error = static_cast<application::AuthError>(authError);

    showMessage(authErrorMessage(error, retryAfterSeconds), isTransientError(error) ? MessageKind::Warning : MessageKind::Error);

    if (error == application::AuthError::RATE_LIMITED && retryAfterSeconds > 0) {
        startCountdown(retryAfterSeconds);
    }
    m_ui->passwordEdit->setFocus();   // the password was cleared: the user retypes it
}

void UserLoginWindow::onCountdownTick()
{
    --m_lockedSeconds;
    if (m_lockedSeconds <= 0) {
        stopCountdown();
        clearMessage();
        updateSignInButton();
        return;
    }
    showMessage(authErrorMessage(application::AuthError::RATE_LIMITED, m_lockedSeconds), MessageKind::Warning);
}

void UserLoginWindow::startCountdown(int seconds)
{
    m_lockedSeconds = seconds;
    m_countdownTimer.start();
    updateSignInButton();
}

void UserLoginWindow::stopCountdown()
{
    m_countdownTimer.stop();
    m_lockedSeconds = 0;
}

void UserLoginWindow::setBusy(bool busy)
{
    m_busy = busy;
    m_ui->loginEdit->setEnabled(!busy);
    m_ui->passwordEdit->setEnabled(!busy);
    m_ui->showPasswordCheck->setEnabled(!busy);
    m_ui->busyBar->setVisible(busy);
    m_ui->signInButton->setText(busy ? tr("Signing in…") : tr("Sign in"));
    updateSignInButton();
}

void UserLoginWindow::updateSignInButton()
{
    const bool inputsFilled = !m_ui->loginEdit->text().trimmed().isEmpty()
                              && !m_ui->passwordEdit->text().isEmpty();

    m_ui->signInButton->setEnabled(inputsFilled && !m_busy && m_lockedSeconds == 0);
}

void UserLoginWindow::showMessage(const QString& text, MessageKind kind)
{
    QLabel* const label = m_ui->messageLabel;
    label->setText(text);
    label->setProperty("state",
                       kind == MessageKind::Error ? QStringLiteral("error") : QStringLiteral("warning"));

    // A dynamic property change is not picked up by the style sheet until we re-polish.
    label->style()->unpolish(label);
    label->style()->polish(label);
    label->setVisible(true);
}

void UserLoginWindow::clearMessage()
{
    m_ui->messageLabel->clear();
    m_ui->messageLabel->setVisible(false);
}

} // namespace ui
